template <int N>
struct Factorial {
    // Compile-time recursion via instantiation
    static constexpr int value = N * Factorial<N - 1>::value;
};

// Base Case Specialization (Stops recursion)
template <>
struct Factorial<0> {
    static constexpr int value = 1;
};

// Example Usage
constexpr int F5 = Factorial<5>::value; // F5 is 120
                                       // Calculated entirely at compile time.

// Using dependent types (Type computation)
template <typename T, int N>
struct ArrayWrapper {
    using Type = T[N];
};
using Int5 = ArrayWrapper<int, 5>::Type; // Equivalent to int[5]
